const cds = require('../../cds')
const { LruCache } = require('./LruCache')
const { isTimeoutError, getTimeoutError } = require('./error')

const LOG = cds.log('remote')

const _tokenCache = new LruCache(cds.env.remote.cache_size)

let BUFFER_MS

const _fetchToken = async ({ clientid, clientsecret, certificate, key, url }, tenant) => {
  const headers = { 'content-type': 'application/x-www-form-urlencoded' }
  if (tenant) headers['x-zid'] = tenant
  let body = 'grant_type=client_credentials'
  let dispatcher

  if (certificate) {
    let Agent
    try {
      ;({ Agent } = require('node:undici'))
    } catch {
      throw new Error(
        'mTLS token fetching requires Node.js 24 or higher (built-in module "node:undici" not available).'
      )
    }
    body += `&client_id=${encodeURIComponent(clientid)}`
    dispatcher = new Agent({ connect: { cert: certificate, key } })
  } else {
    headers.authorization = 'Basic ' + Buffer.from(`${clientid}:${clientsecret}`).toString('base64')
  }

  const { timeout } = cds.env.remote
  const signal = AbortSignal.timeout(cds.utils.ms4(timeout))
  let res
  try {
    res = await fetch(url + '/oauth/token', { method: 'POST', headers, body, dispatcher, signal })
  } catch (e) {
    if (isTimeoutError(e)) throw getTimeoutError(e, 'OAuth2 token request', timeout)
    throw e
  }
  if (!res.ok) throw Object.assign(new Error('OAuth2 token request failed.'), { statusCode: res.status })
  const json = await res.json()
  if (!json.access_token) throw new Error('OAuth2 token response missing access_token.')
  return json
}

/**
 * Returns a cached OAuth2 client credentials token, fetching a new one when absent or expired.
 * @param {{ clientid, clientsecret?, url, certificate?, key? }} creds
 * @param {string} [tenant]
 * @returns {Promise<string>} access_token
 */
const getToken = async (creds, tenant) => {
  const key = [creds.clientid, tenant].filter(Boolean).join(':')
  const cached = _tokenCache.get(key)
  if (cached) {
    LOG._debug && LOG.debug(`OAuth2 token for '${key}' served from cache`)
    return cached
  }

  LOG._debug && LOG.debug(`Fetching OAuth2 token for '${key}' from ${creds.url}`)
  const promise = _fetchToken(creds, tenant)
    .then(({ access_token, expires_in = 60 * 60 }) => {
      const expiresInMs = expires_in * 1000
      BUFFER_MS ??= cds.utils.ms4(cds.env.remote.cache_expiry_buffer)
      const ttl = Math.max(0, expiresInMs - BUFFER_MS)
      LOG._debug && LOG.debug(`OAuth2 token for '${key}' cached for ${ttl}ms`)
      _tokenCache.set(key, access_token, ttl)
      return access_token
    })
    .catch(err => {
      LOG.warn(`Failed to fetch OAuth2 token for '${key}':`, err.message)
      _tokenCache.delete(key)
      throw err
    })

  // store promise immediately to deduplicate concurrent in-flight requests
  _tokenCache.set(key, promise)
  return promise
}

module.exports = { getToken }
